diff --git a/xds/src/main/java/io/grpc/xds/internal/matcher/CelCommon.java b/xds/src/main/java/io/grpc/xds/internal/matcher/CelCommon.java
--- a/xds/src/main/java/io/grpc/xds/internal/matcher/CelCommon.java
+++ b/xds/src/main/java/io/grpc/xds/internal/matcher/CelCommon.java
@@ -0,0 +1,134 @@
+/*
