+ * limitations under the License.
+ */
+
+package io.grpc.xds.internal.matcher;
+
+import com.google.common.base.Preconditions;
+import io.grpc.Metadata;
+
+public final class MatchContext {
+  private final Metadata metadata;
+  private final String path;
+  private final String host;
+  private final String method;
+
+  public MatchContext(Metadata metadata, String path,
+      String host, String method) {
+    this.metadata = Preconditions.checkNotNull(metadata, "metadata");
+    this.path = Preconditions.checkNotNull(path, "path");
+    this.host = Preconditions.checkNotNull(host, "host");
+    this.method = Preconditions.checkNotNull(method, "method");
+  }
+
+  public Metadata getMetadata() {
+    return metadata;
+  }
+  
+  public String getPath() {
+    return path;
+  }
+  
+  public String getHost() {
+    return host;
+  }
+  
+  public String getMethod() {
+    return method;
+  }
+
+  public static Builder newBuilder() {
+    return new Builder();
+  }
+
+  public static final class Builder {
+    private Metadata metadata = new Metadata();
+    private String path;
+    private String host;
+    private String method;
+
+    public Builder setMetadata(Metadata metadata) {
+      this.metadata = metadata;
+      return this;
+    }
+
+    public Builder setPath(String path) {
+      this.path = path;
+      return this;
+    }
+
+    public Builder setHost(String host) {
+      this.host = host;
+      return this;
+    }
+
+    public Builder setMethod(String method) {
+      this.method = method;
+      return this;
+    }
+
+    public MatchContext build() {
+      return new MatchContext(metadata, path, host, method);
+    }
+  }
+}

diff --git a/xds/src/test/java/io/grpc/xds/internal/matcher/CelCommonTest.java b/xds/src/test/java/io/grpc/xds/internal/matcher/CelCommonTest.java
